import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_inv_send(self):
        class T:
            def send(self, b):
                return len(b)
        self.assertEqual(m.inv_send([1, 2], T()), 2)

    def test_s2_inv_filter_by(self):
        rows = [{"type": "a"}, {"type": "b"}]
        self.assertEqual(m.inv_filter_by(rows, type="a"), [{"type": "a"}])

    def test_s3_inv_collect_item(self):
        self.assertEqual(m.inv_collect_item("a", []), ["a"])
        self.assertEqual(m.inv_collect_item("b", ["a"]), ["a", "b"])


if __name__ == "__main__":
    unittest.main()

