import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_cour_send(self):
        class T:
            def send(self, b):
                return len(b)
        self.assertEqual(m.cour_send([1, 2], T()), 2)

    def test_s2_cour_reminder_template(self):
        template, ref = m.cour_reminder_template(19)
        self.assertEqual(template, "Reminder: parcel {parcel_id} is due")
        self.assertEqual(template.format(parcel_id=ref), "Reminder: parcel 19 is due")

    def test_s3_cour_total_cost(self):
        self.assertEqual(m.cour_total_cost([1.5, 2.5], 0), 4.0)


if __name__ == "__main__":
    unittest.main()

