    for n in ast.walk(tree):
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            check_function(n, warn)
    check_blocks(tree, warn)
    return ['%s:%d: %s %s' % (path, l, c, m) for l, c, m in sorted(set(found))]


