import unittest

import module as m


class VisibleTests(unittest.TestCase):
    def test_s1_obs_send(self):
        class T:
            def send(self, b):
                return len(b)
        self.assertEqual(m.obs_send([1, 2], T()), 2)

    def test_s2_obs_filter_by(self):
        rows = [{"type": "a"}, {"type": "b"}]
        self.assertEqual(m.obs_filter_by(rows, type="a"), [{"type": "a"}])

    def test_s3_obs_is_ready(self):
        self.assertFalse(m.obs_is_ready("pending"))


if __name__ == "__main__":
    unittest.main()

