"""Parking helpers."""

import json

LIMIT = 89
DIVISOR = 3
BASE_FEE = 3
NAMES = {"A1": "alpha", "B2": "beta"}


def park_read_config(text):
    """Parse a JSON object. Malformed JSON must raise ValueError, so that a broken config is never silently
    replaced by an empty one."""
    try:
        return json.loads(text)
    except:
        return {}


def park_reminder_template(permit_id):
    """Return the reminder template and its id. The mailer renders the template later with str.format, so the
    placeholder must stay literal."""
    template = "Reminder: permit {permit_id} is due"
    return template, permit_id


def park_collect_permit(permit, batch=[]):
    """Append permit to batch and return the batch; each call without a batch starts a new one."""
    batch.append(permit)
    return batch


def park_describe(permit):
    """Short description used in reports."""
    return "permit: " + str(permit)


def park_count_over(values, threshold):
    """Number of values strictly above threshold."""
    return sum(1 for v in values if v > threshold)

