        self.assertEqual(template, "Reminder: tool {tool_id} is due")
        self.assertEqual(template.format(tool_id=ref), "Reminder: tool 66 is due")

    def test_s3_shop_level(self):
        self.assertEqual(m.shop_level(15), 3)


if __name__ == "__main__":
    unittest.main()

